import http from 'node:http';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const DATA_FILE = path.join(__dirname, 'books.json');
const PORT = process.env.PORT ? Number(process.env.PORT) : 3000;

function loadBooks() {
  try {
    if (!fs.existsSync(DATA_FILE)) {
      fs.writeFileSync(DATA_FILE, '[]', 'utf8');
      return [];
    }
    const raw = fs.readFileSync(DATA_FILE, 'utf8').trim();
    if (!raw) return [];
    const data = JSON.parse(raw);
    return Array.isArray(data) ? data : [];
  } catch {
    return [];
  }
}

function saveBooks(books) {
  const dir = path.dirname(DATA_FILE);
  if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
  fs.writeFileSync(DATA_FILE, JSON.stringify(books, null, 2), 'utf8');
}

function generateId() {
  return Date.now().toString(36) + Math.random().toString(36).slice(2, 7);
}

function escapeHtml(s = '') {
  return String(s)
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;')
    .replaceAll("'", '&#39;');
}

function layout(title, body) {
  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>${escapeHtml(title)}</title>
<style>
*{box-sizing:border-box;font-family:system-ui,-apple-system,Segoe UI,Roboto,sans-serif}
body{max-width:760px;margin:2rem auto;padding:0 1rem;color:#111;line-height:1.5}
h1 a{color:inherit;text-decoration:none}
h2{margin-top:2rem;border-bottom:1px solid #ddd;padding-bottom:.3rem}
.card{border:1px solid #ddd;border-radius:8px;padding:.8rem 1rem;margin:.6rem 0}
.card a{font-weight:600;color:#0b57d0;text-decoration:none}
.card a:hover{text-decoration:underline}
.muted{color:#666;font-size:.9rem}
form{border:1px solid #ddd;border-radius:8px;padding:1rem;margin:1rem 0;background:#fafafa}
label{display:block;margin:.5rem 0 .2rem;font-weight:600}
input,textarea{width:100%;padding:.5rem;border:1px solid #bbb;border-radius:6px}
textarea{min-height:80px}
button{margin-top:.7rem;padding:.55rem 1rem;border:0;background:#0b57d0;color:#fff;border-radius:6px;cursor:pointer}
button:hover{background:#0840a0}
button.secondary{background:#e8e8e8;color:#222}
.badge{display:inline-block;background:#e6f0ff;color:#0b57d0;border-radius:999px;padding:.1rem .6rem;font-size:.8rem;margin-left:.4rem}
.badge.done{background:#def7e5;color:#0a6b2e}
.empty{color:#666;font-style:italic}
a.btn{display:inline-block;margin-top:1rem;color:#0b57d0}
</style>
</head>
<body>
<h1><a href="/">My Books</a></h1>
${body}
</body>
</html>`;
}

function renderHome(books) {
  const reading = books.filter(b => b.status !== 'finished');
  const finished = books.filter(b => b.status === 'finished');

  const list = (arr) => {
    if (!arr.length) return `<p class="empty">No books yet.</p>`;
    return arr.map(b => `
      <div class="card">
        <a href="/books/${escapeHtml(b.id)}">${escapeHtml(b.title)}</a>
        <span class="badge ${b.status === 'finished' ? 'done' : ''}">${escapeHtml(b.status === 'finished' ? 'Finished' : 'Reading')}</span>
        <div class="muted">by ${escapeHtml(b.author || 'Unknown')}</div>
        ${b.notes ? `<div class="muted" style="margin-top:.3rem">${escapeHtml(b.notes.slice(0,120))}${b.notes.length>120?'…':''}</div>` : ''}
        ${b.status !== 'finished' ? `<form method="POST" action="/books/${escapeHtml(b.id)}/finish" style="border:0;background:transparent;padding:0;margin:.5rem 0 0"><button class="secondary" type="submit">Mark as finished</button></form>` : ''}
      </div>`).join('');
  };

  return layout('My Books', `
    <section>
      <h2>Currently Reading</h2>
      ${list(reading)}
    </section>
    <section>
      <h2>Finished</h2>
      ${list(finished)}
    </section>

    <section>
      <h2>Add a Book</h2>
      <form method="POST" action="/books">
        <label for="title">Title *</label>
        <input id="title" name="title" required placeholder="e.g. Dune">

        <label for="author">Author *</label>
        <input id="author" name="author" required placeholder="e.g. Frank Herbert">

        <label for="notes">Notes</label>
        <textarea id="notes" name="notes" placeholder="Your thoughts, quotes..."></textarea>

        <label for="status">Status</label>
        <select name="status" id="status" style="width:100%;padding:.5rem;border:1px solid #bbb;border-radius:6px">
          <option value="reading">Currently Reading</option>
          <option value="finished">Finished</option>
        </select>

        <button type="submit">Add book</button>
      </form>
    </section>
  `);
}

function renderDetail(book) {
  if (!book) return layout('Not found', `<p>Book not found.</p><a class="btn" href="/">← Back to list</a>`);
  return layout(book.title, `
    <div class="card">
      <h2 style="margin:0 0 .2rem;border:0;padding:0">${escapeHtml(book.title)} <span class="badge ${book.status==='finished'?'done':''}">${escapeHtml(book.status)}</span></h2>
      <div class="muted">by ${escapeHtml(book.author || 'Unknown')}</div>
      ${book.notes ? `<p style="white-space:pre-wrap;margin-top:1rem">${escapeHtml(book.notes)}</p>` : `<p class="empty">No notes yet.</p>`}
      ${book.status !== 'finished' ? `<form method="POST" action="/books/${escapeHtml(book.id)}/finish" style="border:0;background:transparent;padding:0"><button type="submit">Mark as finished</button></form>` : ''}
    </div>
    <a class="btn" href="/">← Back to list</a>
    <p class="muted" style="margin-top:1rem">Shareable link: <a href="/books/${escapeHtml(book.id)}">/books/${escapeHtml(book.id)}</a></p>
  `);
}

function parseBody(req) {
  return new Promise(resolve => {
    let data = '';
    req.on('data', c => data += c);
    req.on('end', () => {
      const ct = (req.headers['content-type'] || '').toLowerCase();
      if (ct.includes('application/json')) {
        try { resolve(JSON.parse(data || '{}')); } catch { resolve({}); }
      } else if (ct.includes('application/x-www-form-urlencoded') || ct.includes('multipart/form-data') ) {
        const params = new URLSearchParams(data);
        const obj = {};
        for (const [k, v] of params) obj[k] = v;
        resolve(obj);
      } else {
        if (data.trim().startsWith('{')) {
          try { resolve(JSON.parse(data)); return; } catch {}
        }
        if (data.includes('=')) {
          const params = new URLSearchParams(data);
          const obj = {};
          for (const [k, v] of params) obj[k] = v;
          if (Object.keys(obj).length) { resolve(obj); return; }
        }
        resolve(data ? { _raw: data } : {});
      }
    });
  });
}

function json(res, status, obj) {
  const body = JSON.stringify(obj);
  res.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8', 'Content-Length': Buffer.byteLength(body) });
  res.end(body);
}

function html(res, status, body) {
  res.writeHead(status, { 'Content-Type': 'text/html; charset=utf-8' });
  res.end(body);
}

function redirect(res, location) {
  res.writeHead(303, { Location: location });
  res.end();
}

export function createServer() {
  const server = http.createServer(async (req, res) => {
    const url = new URL(req.url, `http://${req.headers.host || 'localhost'}`);
    const pathname = url.pathname;
    const method = req.method;

    if (method === 'GET' && (pathname === '/' || pathname === '/index.html')) {
      const books = loadBooks();
      return html(res, 200, renderHome(books));
    }

    if (method === 'GET' && pathname.startsWith('/books/') && !pathname.endsWith('/finish')) {
      const id = pathname.replace('/books/', '').replace(/\/$/, '');
      const books = loadBooks();
      const book = books.find(b => String(b.id) === String(id));
      if (!book) return html(res, 404, renderDetail(null));
      return html(res, 200, renderDetail(book));
    }
    if (method === 'GET' && pathname.startsWith('/book/')) {
      const id = pathname.replace('/book/', '').replace(/\/$/, '');
      const books = loadBooks();
      const book = books.find(b => String(b.id) === String(id));
      if (!book) return html(res, 404, renderDetail(null));
      return html(res, 200, renderDetail(book));
    }

    if (method === 'GET' && pathname === '/api/books') {
      return json(res, 200, loadBooks());
    }
    if (method === 'GET' && pathname.startsWith('/api/books/')) {
      const id = pathname.replace('/api/books/', '').replace(/\/$/, '');
      const books = loadBooks();
      const book = books.find(b => String(b.id) === String(id));
      if (!book) return json(res, 404, { error: 'Not found' });
      return json(res, 200, book);
    }

    if ((method === 'POST' || method === 'PUT' || method === 'PATCH') && (pathname === '/books' || pathname === '/api/books' || pathname === '/api/books/' )) {
      const body = await parseBody(req);
      const title = (body.title || '').toString().trim();
      const author = (body.author || '').toString().trim();
      const notes = (body.notes || '').toString();
      const status = body.status === 'finished' ? 'finished' : 'reading';
      if (!title) {
        const wantsJson = pathname.startsWith('/api') || (req.headers.accept||'').includes('application/json');
        if (wantsJson) return json(res, 400, { error: 'Title is required' });
        return html(res, 400, layout('Error', `<p>Title is required.</p><a href="/">Back</a>`));
      }
      const books = loadBooks();
      const book = { id: generateId(), title, author, notes, status, createdAt: new Date().toISOString() };
      books.push(book);
      saveBooks(books);
      const wantsJson = pathname.startsWith('/api') || (req.headers.accept||'').includes('application/json') || (req.headers['content-type']||'').includes('application/json');
      if (wantsJson) return json(res, 201, book);
      return redirect(res, '/');
    }

    const finishMatch = pathname.match(/^\/(?:api\/)?books\/([^\/]+)\/finish\/?$/)
      || pathname.match(/^\/books\/([^\/]+)\/(?:finish|done|complete)\/?$/)
      || pathname.match(/^\/api\/books\/([^\/]+)\/(?:finish|done|complete)\/?$/);
    if (finishMatch && (method === 'POST' || method === 'PATCH' || method === 'PUT' || method === 'POST')) {
      const id = finishMatch[1];
      const books = loadBooks();
      const book = books.find(b => String(b.id) === String(id));
      if (!book) {
        if (pathname.startsWith('/api')) return json(res, 404, { error: 'Not found' });
        return html(res, 404, renderDetail(null));
      }
      book.status = 'finished';
      saveBooks(books);
      const wantsJson = pathname.startsWith('/api') || (req.headers.accept||'').includes('application/json');
      if (wantsJson) return json(res, 200, book);
      const referer = req.headers.referer || '/';
      if (pathname.startsWith('/api')) return json(res, 200, book);
      return redirect(res, req.headers.referer && req.headers.referer.includes('/books/') ? `/books/${book.id}` : '/');
    }

    if ((method === 'PATCH' || method === 'PUT' || method === 'POST') && pathname.startsWith('/api/books/')) {
      const id = pathname.replace('/api/books/', '').split('/')[0];
      const books = loadBooks();
      const book = books.find(b => String(b.id) === String(id));
      if (!book) return json(res, 404, { error: 'Not found' });
      const body = await parseBody(req);
      if (body.status) book.status = body.status === 'finished' ? 'finished' : 'reading';
      if (body.title !== undefined) book.title = String(body.title);
      if (body.author !== undefined) book.author = String(body.author);
      if (body.notes !== undefined) book.notes = String(body.notes);
      saveBooks(books);
      return json(res, 200, book);
    }

    if (method === 'GET' && pathname === '/health') return json(res, 200, { ok: true });

    return html(res, 404, layout('Not found', `<p>Page not found: ${escapeHtml(pathname)}</p><a href="/">Home</a>`));
  });
  return server;
}

if (import.meta.url === `file://${process.argv[1]}` || process.argv[1]?.endsWith('server.js')) {
  const server = createServer();
  server.listen(PORT, () => {
    console.log(`Book tracker listening on http://localhost:${PORT}`);
    console.log(`Data file: ${DATA_FILE}`);
  });
}

