.card a{font-weight:600;color:#0b57d0;text-decoration:none}
.card a:hover{text-decoration:underline}
.muted{color:#666;font-size:.9rem}
form{border:1px solid #ddd;border-radius:8px;padding:1rem;margin:1rem 0;background:#fafafa}
label{display:block;margin:.5rem 0 .2rem;font-weight:600}
input,textarea{width:100%;padding:.5rem;border:1px solid #bbb;border-radius:6px}
textarea{min-height:80px}
button{margin-top:.7rem;padding:.55rem 1rem;border:0;background:#0b57d0;color:#fff;border-radius:6px;cursor:pointer}
button:hover{background:#0840a0}
button.secondary{background:#e8e8e8;color:#222}
.badge{display:inline-block;background:#e6f0ff;color:#0b57d0;border-radius:999px;padding:.1rem .6rem;font-size:.8rem;margin-left:.4rem}
.badge.done{background:#def7e5;color:#0a6b2e}
.empty{color:#666;font-style:italic}
a.btn{display:inline-block;margin-top:1rem;color:#0b57d0}
</style>
</head>
<body>
<h1><a href="/">My Books</a></h1>
${body}
</body>
</html>`;
}

function renderHome(books) {
  const reading = books.filter(b => b.status !== 'finished');
  const finished = books.filter(b => b.status === 'finished');

  const list = (arr) => {
    if (!arr.length) return `<p class="empty">No books yet.</p>`;
    return arr.map(b => `
      <div class="card">
        <a href="/books/${escapeHtml(b.id)}">${escapeHtml(b.title)}</a>
        <span class="badge ${b.status === 'finished' ? 'done' : ''}">${escapeHtml(b.status === 'finished' ? 'Finished' : 'Reading')}</span>
        <div class="muted">by ${escapeHtml(b.author || 'Unknown')}</div>
        ${b.notes ? `<div class="muted" style="margin-top:.3rem">${escapeHtml(b.notes.slice(0,120))}${b.notes.length>120?'…':''}</div>` : ''}
        ${b.status !== 'finished' ? `<form method="POST" action="/books/${escapeHtml(b.id)}/finish" style="border:0;background:transparent;padding:0;margin:.5rem 0 0"><button class="secondary" type="submit">Mark as finished</button></form>` : ''}
      </div>`).join('');
  };

  return layout('My Books', `
    <section>
      <h2>Currently Reading</h2>
      ${list(reading)}
    </section>
    <section>
      <h2>Finished</h2>
      ${list(finished)}
    </section>

    <section>
      <h2>Add a Book</h2>
      <form method="POST" action="/books">
        <label for="title">Title *</label>
        <input id="title" name="title" required placeholder="e.g. Dune">

        <label for="author">Author *</label>
        <input id="author" name="author" required placeholder="e.g. Frank Herbert">

        <label for="notes">Notes</label>
        <textarea id="notes" name="notes" placeholder="Your thoughts, quotes..."></textarea>

        <label for="status">Status</label>
        <select name="status" id="status" style="width:100%;padding:.5rem;border:1px solid #bbb;border-radius:6px">
          <option value="reading">Currently Reading</option>
          <option value="finished">Finished</option>
        </select>

        <button type="submit">Add book</button>
      </form>
    </section>
  `);
}

function renderDetail(book) {
  if (!book) return layout('Not found', `<p>Book not found.</p><a class="btn" href="/">← Back to list</a>`);
  return layout(book.title, `
    <div class="card">
      <h2 style="margin:0 0 .2rem;border:0;padding:0">${escapeHtml(book.title)} <span class="badge ${book.status==='finished'?'done':''}">${escapeHtml(book.status)}</span></h2>
      <div class="muted">by ${escapeHtml(book.author || 'Unknown')}</div>
      ${book.notes ? `<p style="white-space:pre-wrap;margin-top:1rem">${escapeHtml(book.notes)}</p>` : `<p class="empty">No notes yet.</p>`}
