}

function html(res, status, body) {
  res.writeHead(status, { 'Content-Type': 'text/html; charset=utf-8' });
  res.end(body);
}

function redirect(res, location) {
  res.writeHead(303, { Location: location });
  res.end();
}

export function createServer() {
  const server = http.createServer(async (req, res) => {
    const url = new URL(req.url, `http://${req.headers.host || 'localhost'}`);
    const pathname = url.pathname;
    const method = req.method;

    if (method === 'GET' && (pathname === '/' || pathname === '/index.html')) {
      const books = loadBooks();
      return html(res, 200, renderHome(books));
    }

    if (method === 'GET' && pathname.startsWith('/books/') && !pathname.endsWith('/finish')) {
      const id = pathname.replace('/books/', '').replace(/\/$/, '');
      const books = loadBooks();
      const book = books.find(b => String(b.id) === String(id));
      if (!book) return html(res, 404, renderDetail(null));
      return html(res, 200, renderDetail(book));
    }
    if (method === 'GET' && pathname.startsWith('/book/')) {
      const id = pathname.replace('/book/', '').replace(/\/$/, '');
      const books = loadBooks();
      const book = books.find(b => String(b.id) === String(id));
      if (!book) return html(res, 404, renderDetail(null));
      return html(res, 200, renderDetail(book));
    }

    if (method === 'GET' && pathname === '/api/books') {
      return json(res, 200, loadBooks());
    }
    if (method === 'GET' && pathname.startsWith('/api/books/')) {
      const id = pathname.replace('/api/books/', '').replace(/\/$/, '');
      const books = loadBooks();
      const book = books.find(b => String(b.id) === String(id));
      if (!book) return json(res, 404, { error: 'Not found' });
      return json(res, 200, book);
    }

    if ((method === 'POST' || method === 'PUT' || method === 'PATCH') && (pathname === '/books' || pathname === '/api/books' || pathname === '/api/books/' )) {
      const body = await parseBody(req);
      const title = (body.title || '').toString().trim();
      const author = (body.author || '').toString().trim();
      const notes = (body.notes || '').toString();
      const status = body.status === 'finished' ? 'finished' : 'reading';
      if (!title) {
        const wantsJson = pathname.startsWith('/api') || (req.headers.accept||'').includes('application/json');
        if (wantsJson) return json(res, 400, { error: 'Title is required' });
        return html(res, 400, layout('Error', `<p>Title is required.</p><a href="/">Back</a>`));
      }
      const books = loadBooks();
      const book = { id: generateId(), title, author, notes, status, createdAt: new Date().toISOString() };
      books.push(book);
      saveBooks(books);
      const wantsJson = pathname.startsWith('/api') || (req.headers.accept||'').includes('application/json') || (req.headers['content-type']||'').includes('application/json');
      if (wantsJson) return json(res, 201, book);
      return redirect(res, '/');
    }

    const finishMatch = pathname.match(/^\/(?:api\/)?books\/([^\/]+)\/finish\/?$/)
      || pathname.match(/^\/books\/([^\/]+)\/(?:finish|done|complete)\/?$/)
      || pathname.match(/^\/api\/books\/([^\/]+)\/(?:finish|done|complete)\/?$/);
    if (finishMatch && (method === 'POST' || method === 'PATCH' || method === 'PUT' || method === 'POST')) {
      const id = finishMatch[1];
      const books = loadBooks();
      const book = books.find(b => String(b.id) === String(id));
      if (!book) {
        if (pathname.startsWith('/api')) return json(res, 404, { error: 'Not found' });
        return html(res, 404, renderDetail(null));
      }
      book.status = 'finished';
      saveBooks(books);
      const wantsJson = pathname.startsWith('/api') || (req.headers.accept||'').includes('application/json');
      if (wantsJson) return json(res, 200, book);
      const referer = req.headers.referer || '/';
      if (pathname.startsWith('/api')) return json(res, 200, book);
      return redirect(res, req.headers.referer && req.headers.referer.includes('/books/') ? `/books/${book.id}` : '/');
    }

    if ((method === 'PATCH' || method === 'PUT' || method === 'POST') && pathname.startsWith('/api/books/')) {
      const id = pathname.replace('/api/books/', '').split('/')[0];
      const books = loadBooks();
      const book = books.find(b => String(b.id) === String(id));
      if (!book) return json(res, 404, { error: 'Not found' });
      const body = await parseBody(req);
      if (body.status) book.status = body.status === 'finished' ? 'finished' : 'reading';
      if (body.title !== undefined) book.title = String(body.title);
      if (body.author !== undefined) book.author = String(body.author);
      if (body.notes !== undefined) book.notes = String(body.notes);
      saveBooks(books);
      return json(res, 200, book);
    }

    if (method === 'GET' && pathname === '/health') return json(res, 200, { ok: true });

    return html(res, 404, layout('Not found', `<p>Page not found: ${escapeHtml(pathname)}</p><a href="/">Home</a>`));
  });
  return server;
}

if (import.meta.url === `file://${process.argv[1]}` || process.argv[1]?.endsWith('server.js')) {
  const server = createServer();
  server.listen(PORT, () => {
    console.log(`Book tracker listening on http://localhost:${PORT}`);
    console.log(`Data file: ${DATA_FILE}`);
  });
}

